//! 🧪️ Original native Thread issuer conserves its paid Arc/frame and zero-release TLS handle lease.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_thread_wake_native_issuer_preserves_affinity_aliases_and_exact_physical_receipts(){
 let(_,startup)=observe(||drop(original_thread_waker()));eprintln!("[DEBUG] explicit original Thread TLS startup before owned wake born={} released={} remains native-thread-owned",startup.0,startup.1);
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};
 for aliases in [0,1,3]{let(waker,birth)=observe(original_thread_waker);let pointer=waker.data();let mut leases:[Option<Waker>;3]=std::array::from_fn(|index|(index<aliases).then(||waker.clone()));
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:original_thread_wake_lease_copy_bytes()-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(admitted,heap)=observe(||admit_original_thread_wake(&waker,denied).unwrap());assert!(admitted.is_none());assert_eq!(heap,(0,0));assert_eq!(waker.data(),pointer);}
 let((source,receipt),heap)=observe(||admit_original_thread_wake(&waker,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);assert_eq!(Arc::as_ptr(&source).cast::<()>(),pointer);
 let wake=waker.clone();std::thread::spawn(move||wake.wake_by_ref()).join().unwrap();let(_,heap)=observe(||drop(waker));assert_eq!(heap,(0,0));for lease in leases.iter().flatten(){assert_eq!(lease.data(),pointer);}let(_,heap)=observe(||for lease in &mut leases{drop(lease.take());});assert_eq!(heap,(0,0));
 assert!(grant.maximum_copy_bytes>=size_of::<OriginalThreadWake>()+size_of::<Arc<OriginalThreadWake>>());let arc_release=semio_framework_value::shared_retirement_allocation_bytes::<OriginalThreadWake>();assert!(grant.maximum_release_bytes>=arc_release);let(original,heap)=observe(||Arc::try_unwrap(source).unwrap_or_else(|_|panic!("original native Thread source aliases drained")));assert_eq!(heap,(0,arc_release));assert_eq!(birth.0,arc_release);
 let(mut cursor,frame_birth)=observe(||original.retirement());assert_eq!(frame_birth,(size_of::<ThreadWakeRetirement>(),0));let frame=cursor.as_ref()as*const dyn RetirementCursor;
 let returned=std::thread::spawn(move||{let(step,heap)=observe(||cursor.close_step(grant));assert!(matches!(step,RetirementStep::BudgetExhausted));assert_eq!(heap,(0,0));assert!(!cursor.terminal_is_empty());cursor}).join().unwrap();cursor=returned;assert!(std::ptr::eq(cursor.as_ref()as*const dyn RetirementCursor,frame));
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:cursor.next_work_byte_demand().unwrap()-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(step,heap)=observe(||cursor.close_step(denied));assert!(matches!(step,RetirementStep::BudgetExhausted));assert_eq!(heap,(0,0));assert!(std::ptr::eq(cursor.as_ref()as*const dyn RetirementCursor,frame));}
 let(step,heap)=observe(||cursor.close_step(grant));let RetirementStep::Progress(receipt)=step else{panic!("original native TLS lease receipt")};assert!(receipt.fits(grant));assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);assert_eq!(heap,(0,0));assert!(cursor.terminal_is_empty());let(_,heap)=observe(||drop(cursor));assert_eq!(heap,(0,size_of::<ThreadWakeRetirement>()));assert_eq!(birth.0+frame_birth.0,arc_release+heap.1);eprintln!("[DEBUG] actual native Thread original aliases={aliases} stdWaker/Arc pointer stable denied/full4096 cross-thread native wake original-thread TLS handle release0 foreignthread retains original cursor all physical original Arc+cursor paid terminalbodyDrop0");}
 struct Foreign;impl std::task::Wake for Foreign{fn wake(self:Arc<Self>){}}
 let foreign=Waker::from(Arc::new(Foreign));let(result,heap)=observe(||admit_original_thread_wake(&foreign,grant));assert!(matches!(result,Err(error)if error.kind==ValueRefusalKind::UnsupportedOwner));assert_eq!(heap,(0,0));
}
